// Palette di colori scuri con nero come base
const vec3[] COLORS_VALUES = vec3[](
    vec3(0), // nero
    vec3(0), // nero
    vec3(0.2, 0.05, 0.25), // viola scuro
    vec3(0.15, 0.3, 0.4), // blu petrolio scuro
    vec3(0.1, 0.2, 0.15), // verde scuro
    vec3(0) // nero
);

const float[] COLORS_POS = float[](0., 10. / 100., 25. / 100., 55. / 100., 85. / 100., 1.);
const bool GRADIENT_BLEND_MODE = true;
const bool ASPECT_RATIO = true;

// Velocità di scorrimento variabile nel tempo
float getScrollX() {
    return 0.15 * sin(iTime * 0.1) + 0.1 * cos(iTime * 0.07);
}

float getScrollY() {
    return 0.2 * cos(iTime * 0.08) - 0.15 * sin(iTime * 0.05);
}

const float PERLIN_SCALE = 8.5f;
const float PERLIN_STRENGTH = 1.75f;
const float GRADIENT_SPEED = -0.25f;
const float FADE_SPEED = 0.3f;
const bool NO_BACKGROUND_VERSION = false;

vec2 randomGradient(vec2 p) {
    p = p + 0.1f;
    float x = dot(p, vec2(139.9, 364.5));
    float y = dot(p, vec2(452.1, 983.6));
    vec2 gradient = sin(vec2(x, y)) * 26435.799f;
    return sin(gradient + iTime * GRADIENT_SPEED);
}

float getPerlinNoise(vec2 uv) {
    vec2 gridUv = fract(uv * PERLIN_SCALE);
    vec2 gridId = floor(uv * PERLIN_SCALE);

    float scBg = dot(randomGradient(gridId), gridUv);
    float scBd = dot(randomGradient(gridId + vec2(1, 0)), gridUv - vec2(1, 0));
    float scHg = dot(randomGradient(gridId + vec2(0, 1)), gridUv - vec2(0, 1));
    float scHd = dot(randomGradient(gridId + vec2(1, 1)), gridUv - vec2(1, 1));

    gridUv = smoothstep(0., 1., gridUv);
    return mix(mix(scBg, scBd, gridUv.x), mix(scHg, scHd, gridUv.x), gridUv.y);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;

    // Movimento variabile nel tempo
    float scrollX = getScrollX();
    float scrollY = getScrollY();
    uv = vec2(uv.x + iTime / 4. * scrollX, uv.y + iTime / 4. * scrollY);

    if(ASPECT_RATIO)
        uv.x *= iResolution.x / iResolution.y;

    float perlin = getPerlinNoise(uv);
    perlin = fract(perlin * PERLIN_STRENGTH);
    float smoothPerlin = fract(smoothstep(0.5, 0., perlin) + fract(iTime / 2. * FADE_SPEED));

    if(NO_BACKGROUND_VERSION)
        smoothPerlin *= fract(smoothstep(0.5, 0., perlin));

    vec3 myColor;
    int colorPosIndex;

    for(colorPosIndex = 0; colorPosIndex < (COLORS_POS.length()); colorPosIndex++) {
        if(fract(smoothPerlin) < COLORS_POS[colorPosIndex])
            break;
    }

    if(GRADIENT_BLEND_MODE) {
        float colorUv = (fract(smoothPerlin) - COLORS_POS[colorPosIndex - 1]) / 
                       (COLORS_POS[colorPosIndex] - COLORS_POS[colorPosIndex - 1]);
        myColor = mix(COLORS_VALUES[colorPosIndex - 1], COLORS_VALUES[colorPosIndex], colorUv);
    } else {
        myColor = COLORS_VALUES[colorPosIndex];
    }

    // Assicuriamoci che i valori molto bassi siano completamente neri
    myColor = mix(vec3(0), myColor, step(0.05, length(myColor)));

    fragColor = vec4(myColor, 1);
}
